// Finite test-owned inputs. Literal Root vectors are never regenerated by MA1.
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { readMa1MethodBinding, type Ma1MethodBinding } from '../../../lib/readiness/official-truth-product-v3/method/contract'

type RootVector = Readonly<{ name: string; draft: unknown; methodDigest: string; packageDigest: string; packageBytes: string }>
export function ma1RootVectors(): readonly Readonly<{ vector: RootVector; binding: Ma1MethodBinding }>[] {
  const bytes = readFileSync(new URL('../../../docs/official-truth-product-v3/MA1_SYNTHETIC_BINDING_REFERENCE_V1.json', import.meta.url))
  assert.equal(createHash('sha256').update(bytes).digest('hex'), '790ecbbf909f53bf76801249bf3dbae7fd5e5a185f68b608dea0e1d96600eeb6')
  const reference = JSON.parse(bytes.toString('utf8')) as { vectors: RootVector[] }
  assert.equal(reference.vectors.length, 3)
  return Object.freeze(reference.vectors.map(vector => {
    const parsed = readMa1MethodBinding(vector.draft, Buffer.from(vector.packageBytes), vector.packageDigest)
    assert.equal(parsed.ok, true)
    if (!parsed.ok) throw Error('ma1 literal binding rejected')
    assert.equal(parsed.value.methodDigest, vector.methodDigest)
    assert.equal(parsed.value.packageDigest, vector.packageDigest)
    return Object.freeze({ vector, binding: parsed.value })
  }))
}
export function ma1SyntheticTuple(seed: string, revision = 1): Ma1MethodBinding {
  // Separate literal scalar tuple fixtures for DB state/race cases; no document approval.
  assert.match(seed, /^[a-z0-9-]{1,30}$/)
  assert.ok(Number.isSafeInteger(revision) && revision >= 1 && revision <= 2147483647)
  return Object.freeze({ methodId: 'ma1-native-' + seed, revision,
    methodDigest: 'a'.repeat(64), packageDigest: 'b'.repeat(64) })
}
export function ma1Operation(index: number): string {
  assert.ok(Number.isSafeInteger(index) && index > 0 && index <= 65535)
  return 'maop1_' + index.toString(16).padStart(32, '0')
}
